//! Byte-for-byte agreement with the independent Python reference (docs/sync-plan.md, раздел 6,
//! приложение А). `sync/vectors/format-v1.json` is generated by `sync/reference/` from the plan
//! alone; the Rust code has to produce exactly these bytes and has to draw its random bytes in
//! exactly the order of Ф31 (the scripted stream must be spent completely).
#![allow(clippy::unwrap_used, clippy::expect_used)]

mod common;

use amby_sync_core::crypto::account::{
    create_account, derive_password_keys, derive_recovery_keys, reset_password, server_auth_hash,
    unwrap_account_key, unwrap_space_key, wrap_account_key, wrap_space_key, Argon2Params,
};
use amby_sync_core::crypto::body::{open_body, seal_body};
use amby_sync_core::crypto::header::{
    canonical_header_json, header_envelope_epoch, open_header, parse_header_json, seal_header,
};
use amby_sync_core::crypto::keys::{AccountKey, BodyId, ItemId, Kek, SpaceId, SpaceKey};
use amby_sync_core::crypto::padme::sealed_body_len;
use amby_sync_core::crypto::recovery_code::RecoveryCode;
use common::{
    array_of, bytes_of, error_name, format_vectors, header_from_value, number, pattern, text,
    unhex, Scripted,
};
use serde_json::Value;
use sha2::{Digest, Sha256};

fn params_of(case: &Value) -> Argon2Params {
    Argon2Params {
        memory_kib: number(case, "memory_kib") as u32,
        iterations: number(case, "iterations") as u32,
        parallelism: number(case, "parallelism") as u32,
    }
}

fn space_key_of(case: &Value) -> SpaceKey {
    SpaceKey::from_bytes(array_of(case, "space_key"), number(case, "epoch") as u32)
}

#[test]
fn password_keys_match_the_reference() {
    // Р5, Р6, О3, О8: password → Argon2id → HKDF → auth_key and KEK, incl. NFD ≡ NFC (Ф6) and
    // parameters above the defaults (Ф7, Ф8); the server hash is SHA-256 of the auth key (Ф5)
    let vectors = format_vectors();
    for case in vectors["password_keys"].as_array().unwrap() {
        let keys = derive_password_keys(
            text(case, "password"),
            &array_of(case, "salt"),
            &params_of(case),
        )
        .unwrap();
        let name = text(case, "name");
        assert_eq!(
            hex::encode(keys.auth_key.as_bytes()),
            text(case, "auth_key"),
            "{name}"
        );
        assert_eq!(
            hex::encode(keys.kek.as_bytes()),
            text(case, "kek"),
            "{name}"
        );
        assert_eq!(
            hex::encode(server_auth_hash(&keys.auth_key)),
            text(case, "auth_key_hash"),
            "{name}"
        );
    }
}

#[test]
fn recovery_codes_and_keys_match_the_reference() {
    // О3, Р5: recovery code → display form and recovery_auth_key / recovery_KEK (Ф10, Ф28–Ф30)
    let vectors = format_vectors();
    for case in vectors["recovery"]["keys"].as_array().unwrap() {
        let code = RecoveryCode::from_bytes(array_of(case, "code"));
        assert_eq!(code.to_display(), text(case, "display"));
        let keys = derive_recovery_keys(&code);
        assert_eq!(
            hex::encode(keys.auth_key.as_bytes()),
            text(case, "recovery_auth_key")
        );
        assert_eq!(hex::encode(keys.kek.as_bytes()), text(case, "recovery_kek"));
    }
}

#[test]
fn recovery_code_parsing_matches_the_reference() {
    // О3, Ф30: tolerant reading (case, separators, O/I/L look-alikes) and exact rejections
    let vectors = format_vectors();
    for case in vectors["recovery"]["valid"].as_array().unwrap() {
        let parsed = RecoveryCode::parse(text(case, "text")).unwrap();
        assert_eq!(
            hex::encode(parsed.as_bytes()),
            text(case, "code"),
            "{:?}",
            text(case, "text")
        );
    }
    for case in vectors["recovery"]["invalid"].as_array().unwrap() {
        let error = RecoveryCode::parse(text(case, "text")).unwrap_err();
        assert_eq!(
            format!("{error:?}"),
            text(case, "error"),
            "{:?}",
            text(case, "text")
        );
    }
}

#[test]
fn account_key_wrapping_matches_the_reference() {
    // Р5, Ф11, Ф13, Ф31: AK wrapped by a KEK = 0x01 ‖ nonce ‖ ciphertext ‖ tag
    for case in format_vectors()["wrap_account_key"].as_array().unwrap() {
        let kek = Kek::from_bytes(array_of(case, "kek"));
        let ak = AccountKey::from_bytes(array_of(case, "account_key"));
        let mut rng = Scripted::from_hex(text(case, "random"));
        let wrapped = wrap_account_key(&kek, &ak, &mut rng);
        rng.assert_spent();
        assert_eq!(hex::encode(&wrapped), text(case, "wrapped"));
        assert_eq!(wrapped.len(), 73);
        assert_eq!(unwrap_account_key(&kek, &wrapped).unwrap(), ak);
    }
}

#[test]
fn space_key_wrapping_matches_the_reference() {
    // Р5, Р6, Ф12, Ф13, Ф31: VK wrapped by AK, bound to space and epoch
    for case in format_vectors()["wrap_space_key"].as_array().unwrap() {
        let ak = AccountKey::from_bytes(array_of(case, "account_key"));
        let space = SpaceId::from_bytes(array_of(case, "space_id"));
        let vk = space_key_of(case);
        let mut rng = Scripted::from_hex(text(case, "random"));
        let wrapped = wrap_space_key(&ak, &space, &vk, &mut rng);
        rng.assert_spent();
        assert_eq!(hex::encode(&wrapped), text(case, "wrapped"));
        let opened = unwrap_space_key(&ak, &space, vk.epoch(), &wrapped).unwrap();
        assert_eq!(opened.as_bytes(), vk.as_bytes());
        assert_eq!(opened.epoch(), vk.epoch());
    }
}

#[test]
fn account_creation_matches_the_reference() {
    // О3, Р5, Ф31: salt, AK, nonce, recovery code, nonce — in this order, nothing else
    for case in format_vectors()["create_account"].as_array().unwrap() {
        let mut rng = Scripted::from_hex(text(case, "random"));
        let account = create_account(text(case, "password"), &params_of(case), &mut rng).unwrap();
        rng.assert_spent();
        let name = text(case, "name");
        assert_eq!(
            hex::encode(account.password.salt),
            text(case, "salt"),
            "{name}"
        );
        assert_eq!(
            hex::encode(account.password.auth_key.as_bytes()),
            text(case, "auth_key"),
            "{name}"
        );
        assert_eq!(
            hex::encode(&account.password.wrapped_account_key),
            text(case, "wrapped_account_key"),
            "{name}"
        );
        assert_eq!(
            hex::encode(account.account_key.as_bytes()),
            text(case, "account_key"),
            "{name}"
        );
        assert_eq!(
            hex::encode(account.recovery_code.as_bytes()),
            text(case, "recovery_code"),
            "{name}"
        );
        assert_eq!(
            account.recovery_code.to_display(),
            text(case, "recovery_display"),
            "{name}"
        );
        assert_eq!(
            hex::encode(account.recovery_auth_key.as_bytes()),
            text(case, "recovery_auth_key"),
            "{name}"
        );
        assert_eq!(
            hex::encode(&account.wrapped_account_key_recovery),
            text(case, "wrapped_account_key_recovery"),
            "{name}"
        );
    }
}

#[test]
fn password_reset_by_recovery_code_matches_the_reference() {
    // О3, Р5, Ф31: the code unwraps AK, a new salt and nonce seal it under the new password
    let vectors = format_vectors();
    let case = &vectors["reset_password"];
    let code = RecoveryCode::from_bytes(array_of(case, "recovery_code"));
    let mut rng = Scripted::from_hex(text(case, "random"));
    let (ak, envelope) = reset_password(
        &code,
        &bytes_of(case, "wrapped_by_recovery"),
        text(case, "new_password"),
        &params_of(case),
        &mut rng,
    )
    .unwrap();
    rng.assert_spent();
    assert_eq!(hex::encode(ak.as_bytes()), text(case, "account_key"));
    assert_eq!(hex::encode(envelope.salt), text(case, "salt"));
    assert_eq!(
        hex::encode(envelope.auth_key.as_bytes()),
        text(case, "auth_key")
    );
    assert_eq!(
        hex::encode(&envelope.wrapped_account_key),
        text(case, "wrapped_account_key")
    );
}

#[test]
fn canonical_header_json_matches_the_reference() {
    // Р6, Р13, Ф14, Ф15: key order, escapes, unknown fields; and parsing gives the header back
    for case in format_vectors()["header_json"].as_array().unwrap() {
        let header = header_from_value(&case["header"]);
        let json = canonical_header_json(&header).unwrap();
        assert_eq!(
            hex::encode(&json),
            text(case, "canonical_hex"),
            "{}",
            text(case, "name")
        );
        assert_eq!(
            parse_header_json(&json).unwrap(),
            header,
            "{}",
            text(case, "name")
        );
    }
}

#[test]
fn header_envelopes_match_the_reference() {
    // Р2, Р6, Ф17, Ф18, Ф31: padded, encrypted and bound to space, item, epoch and version
    for case in format_vectors()["header_envelope"].as_array().unwrap() {
        let name = text(case, "name");
        let vk = space_key_of(case);
        let space = SpaceId::from_bytes(array_of(case, "space_id"));
        let item = ItemId::from_bytes(array_of(case, "item_id"));
        let header = header_from_value(&case["header"]);
        let mut rng = Scripted::from_hex(text(case, "random"));
        let envelope = seal_header(&vk, &space, &item, &header, &mut rng).unwrap();
        rng.assert_spent();
        assert_eq!(hex::encode(&envelope), text(case, "envelope"), "{name}");
        assert_eq!(
            header_envelope_epoch(&envelope).unwrap(),
            vk.epoch(),
            "{name}"
        );
        let opened = open_header(&vk, &space, &item, number(case, "version"), &envelope).unwrap();
        assert_eq!(opened, header, "{name}");
    }
}

#[test]
fn header_envelopes_from_the_reference_are_rejected_for_the_right_reason() {
    // Р6, Р13, Р9, С5, С13: authenticated but invalid headers (padding, version, format, path, JSON)
    let vectors = format_vectors();
    let cases = vectors["header_negative"].as_array().unwrap();
    assert!(cases.len() >= 10, "the negative header vectors are missing");
    for case in cases {
        let name = text(case, "name");
        let vk = space_key_of(case);
        let space = SpaceId::from_bytes(array_of(case, "space_id"));
        let item = ItemId::from_bytes(array_of(case, "item_id"));
        let error = open_header(
            &vk,
            &space,
            &item,
            number(case, "version"),
            &bytes_of(case, "envelope"),
        )
        .unwrap_err();
        assert_eq!(error_name(&error), text(case, "error"), "{name}");
    }
}

#[test]
fn bodies_match_the_reference() {
    // Р6, О7, Ф20–Ф24, Ф26, Ф31: STREAM chunks, Padmé padding, byte-exact content
    let vectors = format_vectors();
    for case in vectors["body"].as_array().unwrap() {
        let name = text(case, "name");
        let vk = space_key_of(case);
        let body_id = BodyId::from_bytes(array_of(case, "body_id"));
        let content = match case["content"]["kind"].as_str().unwrap() {
            "hex" => bytes_of(&case["content"], "hex"),
            _ => pattern(number(&case["content"], "len") as usize),
        };
        assert_eq!(content.len() as u64, number(case, "size"), "{name}");
        let content_hash = array_of::<32>(case, "content_hash");

        let mut rng = Scripted::from_hex(text(case, "random"));
        let sealed = seal_body(&vk, &body_id, &content, &mut rng).unwrap();
        rng.assert_spent();
        assert_eq!(sealed.len() as u64, number(case, "sealed_len"), "{name}");
        assert_eq!(
            sealed_body_len(content.len() as u64).unwrap(),
            number(case, "sealed_len"),
            "{name}"
        );
        assert_eq!(
            hex::encode(Sha256::digest(&sealed)),
            text(case, "sealed_sha256"),
            "{name}"
        );
        if let Some(full) = case["sealed"].as_str() {
            assert_eq!(hex::encode(&sealed), full, "{name}");
            // the body written by the reference opens to the exact content
            let opened = open_body(
                &vk,
                &body_id,
                content.len() as u64,
                &content_hash,
                &unhex(full),
            )
            .unwrap();
            assert_eq!(opened, content, "{name}");
        }
        let opened =
            open_body(&vk, &body_id, content.len() as u64, &content_hash, &sealed).unwrap();
        assert_eq!(opened, content, "{name}");
    }
}

#[test]
fn bodies_from_the_reference_are_rejected_for_the_right_reason() {
    // Р6, С5, Ф22–Ф25: authenticated but invalid bodies (padding, length, last flag, epoch, ...)
    let vectors = format_vectors();
    let cases = vectors["body_negative"].as_array().unwrap();
    assert!(cases.len() >= 8, "the negative body vectors are missing");
    for case in cases {
        let name = text(case, "name");
        let vk = space_key_of(case);
        let body_id = BodyId::from_bytes(array_of(case, "body_id"));
        let error = open_body(
            &vk,
            &body_id,
            number(case, "size"),
            &array_of(case, "content_hash"),
            &bytes_of(case, "sealed"),
        )
        .unwrap_err();
        assert_eq!(error_name(&error), text(case, "error"), "{name}");
    }
}

#[test]
fn path_syntax_matches_the_reference() {
    // Р9, Р6, Ф33: the same paths are accepted and refused as in the reference, when sealing
    let vectors = format_vectors();
    let cases = vectors["paths"].as_array().unwrap();
    assert!(cases.len() >= 20, "the path vectors are missing");
    let vk = SpaceKey::from_bytes([0x11; 32], 1);
    let space = SpaceId::from_bytes([0xA1; 16]);
    let item = ItemId::from_bytes([0xB2; 16]);
    for case in cases {
        let path = text(case, "path");
        let header = common::file_header(1, path);
        let sealed = seal_header(&vk, &space, &item, &header, &mut common::SeedRandom(1));
        let shown: String = path.chars().take(30).collect();
        if case["valid"].as_bool().unwrap() {
            let envelope = sealed.unwrap_or_else(|e| panic!("{shown:?} refused: {e:?}"));
            assert_eq!(
                open_header(&vk, &space, &item, 1, &envelope).unwrap().path,
                path
            );
        } else {
            assert_eq!(
                sealed.unwrap_err(),
                amby_sync_core::crypto::CryptoError::InvalidPath,
                "{shown:?}"
            );
        }
    }
}
